  const LANGS = ['sk', 'cs', 'en', 'de', 'es'];

  function install() {
    const api = window.DomainI18n;
    if (!api || !api.dict) {
      console.warn('[i18n-ui-core] Brak window.DomainI18n — plik musi być ładowany PO i18n-domain.js.');
      return false;
    }
    const stats = {};
    LANGS.forEach((lang, idx) => {
      const d = api.dict[lang] || (api.dict[lang] = {});
      let added = 0;
      // Nie nadpisujemy kluczy, które słowniki wcześniejsze już znają —
      // tam jest źródło prawdy, tutaj wyłącznie uzupełnienie braków.
      for (const row of T.concat(PH)) {
        const pl = row[0], tr = row[idx + 1];
        if (tr && !(pl in d)) { d[pl] = tr; added++; }
      }
      stats[lang] = added;
    });
    // at === de w i18n-domain.js (ten sam obiekt), więc zwykle 0 — ale gdyby się
    // kiedyś rozjechały, austriacki i tak dostanie komplet niemieckiego.
    const at = api.dict.at || (api.dict.at = {});
    let addedAt = 0;
    for (const row of T.concat(PH)) if (row[4] && !(row[0] in at)) { at[row[0]] = row[4]; addedAt++; }
    stats.at = addedAt;

    console.info('[i18n-ui-core] Dopisano kluczy:', stats);
    if (typeof api.apply === 'function') api.apply();
    return true;
  }

  if (!install()) {
    // i18n-domain.js startuje na DOMContentLoaded — spróbuj ponownie po załadowaniu.
    document.addEventListener('DOMContentLoaded', install);
  }
